import{z as o,x as s,o as e,c as l,q as B,j as n,D as a,d as t,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"经济数据的来源与口径","description":"","frontmatter":{"title":"经济数据的来源与口径","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ec-data-sources.md","filePath":"econ/ec-data-sources.md","lastUpdated":1791413859000}'),c={name:"econ/ec-data-sources.md"};function d(p,E,D,F,h,f){const A=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=B('<h1 id="经济数据的来源与口径" tabindex="-1">经济数据的来源与口径 <a class="header-anchor" href="#经济数据的来源与口径" aria-label="Permalink to &quot;经济数据的来源与口径&quot;">​</a></h1><div class="epigraph"><p>大数据没有替换经济学的问题，替换的是哪些量测得到、哪些约束验得起；数据的第一性质永远是它是怎么被生成的。</p><footer>—— 据 Einav and Levin, Economics in the Age of Big Data, Science 2014 整理</footer></div><p><a href="/econ/ca-map">上一课</a>把因果方法的学科应用收束：变异从制度缝隙来，读数为谁而估，跨域搬运过假设、目标、搬运的三问审计。缺口再往前挪一步：无论测的是什么，量本身从哪来、按什么口径计算，先于一切估计。本课是「经济数据与计算」的第一课：行政数据怎么进协议、大数据与调查怎么组合、计算环境怎么冻结、规模化怎么排梯子，都默认你已经把「来源谱系加口径检查」当作接触任何数据集的第一个动作。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经济数据大多不是为研究而生：它为收税、发工资、记账、成交而沉淀。生成目的与使用目的的错位留下三个缺口。量与构念错位：<a href="/econ/gdp-accounts">GDP 三种算法</a>已经钉过，增加值是约定边界内的生产，不是福利；CPI 的篮子与权重同样是约定（<a href="/econ/cpi-vs-pce">CPI 与 PCE</a>），拿统计口径直接当理论构念，第一行就错。口径漂移：定义、覆盖、参考期随机构与政策而变，修订还会改写历史。可得性与识别错配：数据里存在哪种变异是来源决定的，而识别设计吃的就是变异。</p><h3 id="来源谱系与口径五查" tabindex="-1">来源谱系与口径五查 <a class="header-anchor" href="#来源谱系与口径五查" aria-label="Permalink to &quot;来源谱系与口径五查&quot;">​</a></h3><p>按生成机制分五类。调查：为测量而生，抽样框清楚，代价是成本高、回答率下滑。行政：为管理而生，覆盖大、时间长，但字段是管理定义。交易与扫描：为成交而生，高频高频次，覆盖停在交易边界内。网络与文本：为传播而生，测量要过<a href="/econ/pm-text-as-data">上一课</a>的三重验证。实验：为识别而生，构念与分配可控，外部有效性另需论证（见<a href="/econ/pe-external-validity">外部有效性</a>）。</p><p>拿到任何数据集先过口径五查：单位与名义/实际，实际值怎么缩、链式指数的坑见<a href="/econ/chain-index-bias">链式指数偏差</a>；<span class="marginnote">名义换实际的一个数字实例：某年名义 GDP 增长 8%，通胀 5%，实际增长约就是 1.08/1.05 − 1 ≈ 2.9%，而不是把 5 直接减掉得 3%。缩不减准这一步，后面所有「增长」的讨论都在比错误的数。</span>参考期与频率，流量还是存量、月历月还是财年；总体与抽样框，<a href="/econ/gdp-accounts">常住与领土</a>那一刀切在谁身上；季节调整，调整程序本身就是滤波模型，取舍与 <a href="/econ/hp-filter-cycles">HP 滤波</a>同类；修订与版本，季度 GDP 先行估计之后约一个月内还要修两次，全面修订约每五年随基准换基。</p><p><span class="marginnote">BLS 每月为 CPI 收集约八万个报价；即便这种「为测量而生」的数据，篮子与网点的更新节奏仍是统计机构的约定——口径不是数据的属性，是生产流程的属性，所以要读手册而不是读表头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',10)),(e(),n(i,null,{default:a(()=>[r(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%9D%A5%E6%BA%90%E8%B0%B1%E7%B3%BB%3A%20%E8%B0%83%E6%9F%A5%2F%E8%A1%8C%E6%94%BF%2F%E4%BA%A4%E6%98%93%2F%E7%BD%91%E7%BB%9C%2F%E5%AE%9E%E9%AA%8C%22%5D%20--%3E%20GEN%5B%22%E8%AF%BB%E7%94%9F%E6%88%90%E6%9C%BA%E5%88%B6%3A%20%E8%B0%81%E4%B8%BA%E4%BD%95%E6%97%B6%E7%82%B9%E8%AE%B0%E5%BD%95%22%5D%0A%20%20GEN%20--%3E%20CK%5B%22%E5%8F%A3%E5%BE%84%E4%BA%94%E6%9F%A5%3A%20%E5%8D%95%E4%BD%8D%2F%E5%8F%82%E8%80%83%E6%9C%9F%2F%E6%80%BB%E4%BD%93%2F%E5%AD%A3%E8%8A%82%E8%B0%83%E6%95%B4%2F%E4%BF%AE%E8%AE%A2%22%5D%0A%20%20CK%20--%3E%20VAR%5B%22%E6%95%B0%E6%8D%AE%E9%87%8C%E5%AD%98%E5%9C%A8%E4%BB%80%E4%B9%88%E5%8F%98%E5%BC%82%22%5D%0A%20%20VAR%20--%3E%20D%7B%22%E8%AF%86%E5%88%AB%E8%AE%BE%E8%AE%A1%E5%90%83%E5%BE%97%E4%B8%8B%E5%90%97%22%7D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20EST%5B%22%E8%BF%9B%E4%BC%B0%E8%AE%A1%E4%B8%8E%E6%8E%A8%E6%96%AD%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20RES%5B%22%E6%8D%A2%E6%9D%A5%E6%BA%90%E6%88%96%E6%8D%A2%E8%AE%BE%E8%AE%A1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p>流程上，读生成机制先于读表：谁录入、在什么激励下录入、漏录意味着什么；然后口径五查，把每个字段的定义史记下来；最后把「存在的变异」与设计对上。要做<a href="/econ/difference-in-differences">双重差分</a>，政策断面与时间断面都得有变异；要用工具变量，来源里得存在排除约束讲得通的移动，弱工具的代价见<a href="/econ/iv-weak-instruments">弱工具变量</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>口径错误无法靠计量补救，因为它进入回归的结构不是白噪声。经典测量误差使系数衰减；<span class="marginnote">直觉类比：经典测量误差像给 y 掷骰子加噪声——骰子与 x 无关，回归为了不被随机噪声牵着走，会把斜率往零收缩，这就是「衰减」。误差与 x 相关时更糟：它会把你根本没测过的东西伪装成规律。</span>非经典误差——比如拿今天的修订序列回测当年决策者面对的 vintage 数据——直接制造不存在的规律：当年的预期对应的是当时看到的数据，不是后来修正的数据。<span class="marginnote">vintage 数据就是「当时那瓶」的数据：决策者在 2008 年 10 月做决定时，手里只有当时发布的 GDP 初值，而不是几年后修正过的终版。回放历史决策必须用当时的版本，否则等于把未来发生的信息偷偷塞给了过去的人。</span>口径错在结构上，还是可救与不可救的分界，可以按「误差与真值的关系」分叉来看。</p>',3)),(e(),n(i,null,{default:a(()=>[r(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%8F%A3%E5%BE%84%E9%94%99%E8%AF%AF%E8%BF%9B%E5%85%A5%E5%9B%9E%E5%BD%92%22%5D%20--%3E%20T%7B%22%E8%AF%AF%E5%B7%AE%E4%B8%8E%E7%9C%9F%E5%80%BC%2F%E8%A7%A3%E9%87%8A%E5%8F%98%E9%87%8F%E7%9B%B8%E5%85%B3%E5%90%97%22%7D%0A%20%20T%20--%3E%7C%22%E4%B8%8D%E7%9B%B8%E5%85%B3%3A%20%E7%BB%8F%E5%85%B8%E6%B5%8B%E9%87%8F%E8%AF%AF%E5%B7%AE%22%7C%20ATT%5B%22%E7%B3%BB%E6%95%B0%E5%90%91%E9%9B%B6%E8%A1%B0%E5%87%8F%2C%20%E4%BC%B0%E8%AE%A1%E5%81%8F%E4%BF%9D%E5%AE%88%22%5D%0A%20%20T%20--%3E%7C%22%E7%9B%B8%E5%85%B3%3A%20%E9%9D%9E%E7%BB%8F%E5%85%B8%E8%AF%AF%E5%B7%AE%22%7C%20FAKE%5B%22%E5%88%B6%E9%80%A0%E4%B8%8D%E5%AD%98%E5%9C%A8%E7%9A%84%E8%A7%84%E5%BE%8B%22%5D%0A%20%20FAKE%20--%3E%20EX%5B%22%E4%BE%8B%3A%20%E7%94%A8%E4%BB%8A%E5%A4%A9%E7%9A%84%E4%BF%AE%E8%AE%A2%E5%BA%8F%E5%88%97%E5%9B%9E%E6%94%BE%E5%BD%93%E5%B9%B4%E5%86%B3%E7%AD%96%22%5D%0A%20%20EX%20--%3E%20FIX%5B%22%E6%94%B9%E7%94%A8%E5%BD%93%E6%97%B6%E5%8F%91%E5%B8%83%E7%9A%84%20vintage%20%E5%BA%8F%E5%88%97%22%5D%0A%20%20ATT%20--%3E%20SRC%5B%22%E8%AE%A1%E9%87%8F%E6%95%91%E4%B8%8D%E4%BA%86%2C%20%E5%8F%AA%E8%83%BD%E5%9B%9E%E6%BA%90%E5%A4%B4%E4%BF%AE%E5%8F%A3%E5%BE%84%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p>这与<a href="/econ/pm-text-as-data">上一课</a>的「今天的词典回放昨天」同源，都是把未来信息泄进测量。变异同理是先定的：采样机制决定了哪个维度有变异、哪个维度被截断，设计是在给定变异上做文章，不是无中生有。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教采集与清洗的工程细节，隐私与访问协议是行政数据课的事；大数据与调查怎么互补、怎么加权，是融合课的事。指数构造的公式在<a href="/econ/price-index-real">价格指数与实际值</a>已经讲过，这里只把它当口径五查的一格。谱系也不是教条：收入在调查、税务、雇主报表里各有一份，多源的校验与组合正是后两课的素材。后课默认你已经会先问：这是谁、为什么、按什么口径记下来的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>经济数据按生成机制分五类：调查、行政、交易扫描、网络文本、实验；每类的偏在生成机制里，不在文件格式里。</li><li>口径五查：单位与名义/实际、参考期、总体与抽样框、季节调整、修订版本；vintage 数据是回放历史的唯一合法口径。</li><li>口径错误是结构性测量误差，计量救不了；识别可用的变异由来源先定。</li><li>读生成机制先于读表：谁录入、为什么、漏掉谁。</li><li>出处：Einav and Levin, <em>Science</em> 2014；Varian, <em>JEP</em> 2014；统计口径据 BLS、BEA 手册整理。</li></ul>',5))])}const C=o(c,[["render",d]]);export{_ as __pageData,C as default};
